    // 直接调用（sRDI 生成的 DLL 用下面这行替代）
    // ((void(*)(void))mem)();
    HANDLE h = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)mem, NULL, 0, NULL);
    WaitForSingleObject(h, INFINITE);
