// rwdrv.c —— WDM 读写驱动骨架（EAC 目标：读/写任意进程虚拟内存）
#include <ntifs.h>
#include <ntddk.h>

#define DEV_NAME  L"\\Device\\rwdrv"
#define SYM_NAME  L"\\DosDevices\\rwdrv"

typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  SrcAddr;   // 目标进程地址
    PVOID  DstAddr;   // 本进程缓冲区
    SIZE_T Size;
    ULONG  Mode;      // 0=read 1=write
} RW_REQ, *PRW_REQ;

static PEPROCESS g_Target = NULL;

// 通过 PID 拿 EPROCESS（PsLookupProcessByProcessId 会加引用，用完必须解）
static NTSTATUS GetTarget(ULONG pid, PEPROCESS* out) {
    return PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, out);
}

// 读写统一走 MmCopyVirtualMemory：不触发目标进程的页保护检查，
// 不会像 ReadProcessMemory 那样在目标里留下线程/句柄痕迹
static NTSTATUS DoCopy(PRW_REQ req) {
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st;
    SIZE_T done = 0;

    st = GetTarget(req->Pid, &src);
    if (!NT_SUCCESS(st)) return st;
    dst = PsGetCurrentProcess();

    if (req->Mode == 0) {
        st = MmCopyVirtualMemory(src, req->SrcAddr, dst, req->DstAddr, req->Size, KernelMode, &done);
    } else {
        st = MmCopyVirtualMemory(dst, req->DstAddr, src, req->SrcAddr, req->Size, KernelMode, &done);
    }
    ObDereferenceObject(src);
    return st;
}

static NTSTATUS DispatchCtl(PDEVICE_OBJECT dev, PIRP irp) {
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG inLen  = sp->Parameters.DeviceIoControl.InputBufferLength;
    ULONG outLen = sp->Parameters.DeviceIoControl.OutputBufferLength;
    ULONG code   = sp->Parameters.DeviceIoControl.IoControlCode;

    if (code == CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
        && inLen == sizeof(RW_REQ)) {
        st = DoCopy((PRW_REQ)irp->AssociatedIrp.SystemBuffer);
        irp->IoStatus.Information = 0;
    } else if (outLen) {
        irp->IoStatus.Information = 0;
    }
    irp->IoStatus.Status = st;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static NTSTATUS DispatchCreate(PDEVICE_OBJECT dev, PIRP irp) {
    UNREFERENCED_PARAMETER(dev);
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING devName, symName;
    PDEVICE_OBJECT dev = NULL;
    NTSTATUS st;

    RtlInitUnicodeString(&devName, DEV_NAME);
    RtlInitUnicodeString(&symName, SYM_NAME);

    st = IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN, 0, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&symName, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    drv->MajorFunction[IRP_MJ_CREATE]         = DispatchCreate;
    drv->MajorFunction[IRP_MJ_CLOSE]          = DispatchCreate;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchCtl;
    return STATUS_SUCCESS;
}
