#include <stdio.h>

typedef NTSTATUS (NTAPI *pNtQSI)(ULONG, PVOID, ULONG, PULONG);
typedef struct { UNICODE_STRING ImageName; ULONG_PTR UniqueProcessId; ULONG_PTR Reserved; } SPSE;

int main(void) {
    pNtQSI NtQuerySystemInformation = (pNtQSI)GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "NtQuerySystemInformation");
    ULONG sz = 1 << 20, ret = 0; PVOID buf = malloc(sz);
    NTSTATUS st = NtQuerySystemInformation(5 /*SystemProcessInformation*/, buf, sz, &ret);
    if (st != 0) { printf("status=0x%08X need=%lu\n", st, ret); return 1; }
    SPSE *p = (SPSE*)buf;
    while (1) {
        if (p->ImageName.Buffer) wprintf(L"PID %5llu  %ls\n", (unsigned long long)p->UniqueProcessId, p->ImageName.Buffer);
        if (p->Reserved == 0) break;
        p = (SPSE*)((BYTE*)p + p->Reserved);
    }
    return 0;
}
```

