### 2.2 W2S（世界坐标转屏幕坐标）

```cpp
struct FVector { float x, y, z; };
struct FRotator { float pitch, yaw, roll; };

bool WorldToScreen(const FVector& world, const FVector& camLoc,
                   const FRotator& camRot, float fov, int sw, int sh,
                   FVector& out) {
    float radPitch = camRot.pitch * (3.14159265f / 180.f);
    float radYaw   = camRot.yaw   * (3.14159265f / 180.f);
    float radRoll  = camRot.roll  * (3.14159265f / 180.f);

    float sp = sinf(radPitch), cp = cosf(radPitch);
    float sy = sinf(radYaw),   cy = cosf(radYaw);
    float sr = sinf(radRoll),  cr = cosf(radRoll);

    float dx = world.x - camLoc.x, dy = world.y - camLoc.y, dz = world.z - camLoc.z;

    float t[3][3] = {
        { cp*cy, cp*sy, sp },
        { sr*sp*cy - cr*sy, sr*sp*sy + cr*cy, -sr*cp },
        { -(cr*sp*cy + sr*sy), cy*sr - cr*sp*sy, cr*cp }
    };

    float rdx = dx*t[0][0] + dy*t[0][1] + dz*t[0][2];
    float rdy = dx*t[1][0] + dy*t[1][1] + dz*t[1][2];
    float rdz = dx*t[2][0] + dy*t[2][1] + dz*t[2][2];

    if (rdz == 0) return false;

    const float tanHalf = tanf(fov * 3.14159265f / 360.f);
    out.x = sw / 2.f + rdx * (sw / 2.f / tanHalf) / rdz;
    out.y = sh / 2.f - rdy * (sh / 2.f / tanHalf) / rdz;
    return rdz > 0.01f;
}
