#define IOCTL_READ_MEM  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQUEST {
    ULONG  Pid;
    PVOID  Address;
    PVOID  Buffer;
    SIZE_T Size;
    SIZE_T BytesDone;
} RW_REQUEST, *PRW_REQUEST;

NTSTATUS ReadProcessMemoryByPid(ULONG pid, PVOID addr, PVOID buf, SIZE_T size, SIZE_T* done) {
    PEPROCESS process = NULL;
    NTSTATUS status = PsLookupProcessByProcessId(ULongToHandle(pid), &process);
    if (!NT_SUCCESS(status)) return status;
    status = MmCopyVirtualMemory(process, addr, PsGetCurrentProcess(), buf, size, KernelMode, done);
    ObDereferenceObject(process);
