}

NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp) {
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(irp);
    PVOID out = irp->AssociatedIrp.SystemBuffer;
    ULONG in_len = stack->Parameters.DeviceIoControl.InputBufferLength;
    ULONG out_len = stack->Parameters.DeviceIoControl.OutputBufferLength;
    NTSTATUS status = STATUS_INVALID_PARAMETER;
    ULONG ret = 0;

    if (stack->Parameters.DeviceIoControl.IoControlCode == IOCTL_READ_MEM
        && in_len >= sizeof(RW_REQUEST) && out_len >= sizeof(RW_REQUEST)) {
        PRW_REQUEST req = (PRW_REQUEST)out;
        size_t done = 0;
        status = ReadProcessMemoryByPid(req->Pid, req->Address, req->Buffer, req->Size, &done);
        if (NT_SUCCESS(status)) { req->BytesDone = done; ret = sizeof(RW_REQUEST); }
    }
    irp->IoStatus.Status = status;
    irp->IoStatus.Information = ret;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return status;
}

