// 多级指针链：offsets 从外到内，最后一项是字段偏移
ULONG_PTR ResolvePtrChain(HANDLE h, ULONG_PTR base, const DWORD* offsets, size_t n) {
    ULONG_PTR addr = base;
    for (size_t i = 0; i < n; ++i) {
        SIZE_T rd = 0;
