```cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

// 占位参数，按实际目标替换
#define PROC_NAME L"[进程名].exe"
#define MODULE_NAME L"[模块名].exe"   // UE4 一般是游戏本体 exe 或 [模块名]-Win64-Shipping.exe

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    CloseHandle(snap);
    return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
    CloseHandle(snap);
    return base;
}

int main() {
    DWORD pid = GetPid(PROC_NAME);
    if (!pid) { printf("pid not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { printf("OpenProcess fail %lu\n", GetLastError()); return 1; }
    uintptr_t base = GetModuleBase(pid, MODULE_NAME);
    printf("pid=%lu base=0x%llX\n", pid, (unsigned long long)base);
    // 下一步：读 base + [UWorld 偏移] 得到 UWorld 指针
    return 0;
}
